/* Admin KPI individual evaluation: position scorecards, evidence, review, void and audit-safe replacement. */
const ADMIN_KPI_STATE={loaded:false,loading:false,error:'',scorecards:[],items:[],assignments:[],evaluations:[],scores:[],comments:[],notices:[],acknowledgements:[]};
const ADMIN_KPI_STATUS={draft:'ร่าง',returned:'ส่งกลับแก้ไข',submitted:'รอตรวจรับ',approved:'รับรองแล้ว',locked:'ล็อกรอบ',voided:'เป็นโมฆะ'};
let ADMIN_KPI_VIEW='admin';

function adminKpiRelevant(){return !!ACCESS_PROFILE&&(canAdminAccess()||canViewDept('ADMIN')||ACCESS_PROFILE.department_code==='KPI');}
function adminKpiCanConfigure(){return !!ACCESS_PROFILE&&(canAdminAccess()||(ACCESS_PROFILE.department_code==='KPI'&&['lead','admin','exec'].includes(AUTH_DB_ROLE)));}
function adminKpiCanStart(){return adminKpiCanConfigure()||MANAGE_DEPTS.includes('ADMIN');}
function adminKpiPositionGroup(position=''){const s=String(position).toLowerCase();if(/บริหาร.*แอดมิน|admin management|management admin/.test(s))return'management';if(/ผู้ช่วยหัวหน้า|รอง.*หัวหน้า|assistant.*(head|lead)|deput.*(head|lead)|หัวหน้า|head|lead/.test(s))return'lead';return'staff';}
function adminKpiCardFor(profile=ACCESS_PROFILE){const group=adminKpiPositionGroup(profile?.position_title);return ADMIN_KPI_STATE.scorecards.find(s=>s.position_group===group);}
function adminKpiProfile(id){return TASK_PROFILES.find(p=>p.id===id)||ACCESS_USERS.find?.(p=>p.id===id)||{id,display_name:id};}
function adminKpiName(id){const p=adminKpiProfile(id);return p.display_name||p.email||id||'—';}
function adminKpiItems(code){return ADMIN_KPI_STATE.items.filter(i=>i.scorecard_code===code).sort((a,b)=>a.sort_order-b.sort_order);}
function adminKpiEvaluation(id){return ADMIN_KPI_STATE.evaluations.find(e=>e.id===id);}
function adminKpiCanReview(e){return !!e&&e.status==='submitted'&&e.evaluator_id!==ACCESS_PROFILE?.id&&(e.reviewer_id===ACCESS_PROFILE?.id||adminKpiCanConfigure());}
function adminKpiTotal(code){return adminKpiItems(code).reduce((n,i)=>n+Number(i.max_score||0),0);}

async function loadAdminKpi(force=false){
 if(!SB||!adminKpiRelevant()||ADMIN_KPI_STATE.loading||(!force&&ADMIN_KPI_STATE.loaded))return;
 ADMIN_KPI_STATE.loading=true;ADMIN_KPI_STATE.error='';
 try{
  const reads=await Promise.all([
   integrityReadAll(()=>SB.from('kpi_scorecards').select('*').eq('active',true),['code']),
   integrityReadAll(()=>SB.from('kpi_scorecard_items').select('*'),['scorecard_code','sort_order']),
   integrityReadAll(()=>SB.from('kpi_evaluator_assignments').select('*'),['evaluatee_id','effective_from']),
   integrityReadAll(()=>SB.from('kpi_evaluations').select('*'),['period_start','id']),
   integrityReadAll(()=>SB.from('kpi_evaluation_scores').select('*'),['evaluation_id','item_id']),
   integrityReadAll(()=>SB.from('kpi_evaluation_comments').select('*'),['evaluation_id','id']),
   integrityReadAll(()=>SB.from('kpi_policy_notices').select('*').eq('active',true),['effective_from','code']),
   integrityReadAll(()=>SB.from('kpi_policy_acknowledgements').select('*'),['notice_code','profile_id'])
  ]);
  const bad=reads.find(r=>r.error);if(bad)throw bad.error;
  ['scorecards','items','assignments','evaluations','scores','comments','notices','acknowledgements'].forEach((key,i)=>ADMIN_KPI_STATE[key]=reads[i].data||[]);
  ADMIN_KPI_STATE.loaded=true;
 }catch(error){ADMIN_KPI_STATE.error=error.message||'เปิดระบบประเมิน KPI Admin ไม่สำเร็จ';}
 finally{ADMIN_KPI_STATE.loading=false;if(VIEW==='kpi')RENDER.kpi();}
}

function adminKpiPolicyHTML(){
 const notice=ADMIN_KPI_STATE.notices.at(-1);if(!notice)return'';
 const ack=ADMIN_KPI_STATE.acknowledgements.some(a=>a.notice_code===notice.code&&a.profile_id===ACCESS_PROFILE.id);
 return `<section class="card admin-kpi-notice"><div class="admin-kpi-notice-icon">!</div><div><span class="admin-kpi-eyebrow">ประกาศจาก ${esc(notice.source_team)}</span><h2>${esc(notice.title)}</h2><div class="admin-kpi-policy-points"><span>ประเมินตามตำแหน่ง</span><span>ใช้ผลงานจริงและหลักฐาน</span><span>ตรวจสอบย้อนหลังได้</span></div><details><summary>อ่านประกาศและมาตรการฉบับเต็ม</summary><p>${esc(notice.body)}</p></details></div><div class="admin-kpi-ack ${ack?'is-ack':''}"><span>${ack?'✓ รับทราบแล้ว':'กรุณาอ่านก่อนยืนยัน'}</span>${ack?'':`<button class="tbtn primary" onclick="ackAdminKpiPolicy('${esc(notice.code)}')">รับทราบประกาศ</button>`}</div></section>`;
}
function adminKpiFlowHTML(){return `<section class="card pad admin-kpi-flow"><h3>ผู้รับผิดชอบการประเมิน</h3><div class="admin-kpi-flow-grid"><div><b>พนักงาน Admin</b><span>ผู้ช่วยหัวหน้า / หัวหน้า</span></div><div><b>รอง</b><span>ผู้ช่วยหัวหน้า</span></div><div><b>ผู้ช่วยหัวหน้า</b><span>หัวหน้า</span></div><div><b>หัวหน้า</b><span>ทีมบริหาร Admin</span></div><div><b>บริหารแอดมิน</b><span>ทีมบริหาร / ทีม KPI</span></div></div><p>ผู้ประเมินห้ามประเมินตนเอง · ทุกคะแนนต้องมีข้อมูลจริงและหลักฐาน · การลงโทษต้องผ่านการตรวจข้อเท็จจริง ไม่เกิดขึ้นอัตโนมัติจากคะแนน</p></section>`;}

function adminKpiTabsHTML(){return `<nav class="admin-kpi-tabs" aria-label="เลือกส่วน KPI"><button class="${ADMIN_KPI_VIEW==='admin'?'active':''}" onclick="adminKpiSetView('admin')"><span>01</span><b>ประเมิน KPI Admin</b><small>กำหนดผู้ประเมิน กรอกคะแนน และตรวจรับ</small></button><button class="${ADMIN_KPI_VIEW==='evidence'?'active':''}" onclick="adminKpiSetView('evidence')"><span>02</span><b>หลักฐาน KPI ทุกแผนก</b><small>ค้นหางานที่แท็กและผลรายเดือน</small></button></nav>`;}
function adminKpiArrangeLegacy(){
 const root=document.getElementById('admin-kpi-control');if(!root)return;
 [...main.children].forEach(el=>{if(el===root||el.classList.contains('crumb')||el.classList.contains('page-h')||el.id==='data-health')return;el.classList.add('admin-kpi-legacy');});
 const anchor=document.getElementById('kpi-work-report');if(anchor&&root.nextElementSibling!==anchor)main.insertBefore(root,anchor);
 main.classList.toggle('admin-kpi-evidence-view',ADMIN_KPI_VIEW==='evidence');
}
function adminKpiSetView(view){ADMIN_KPI_VIEW=view==='evidence'?'evidence':'admin';adminKpiArrangeLegacy();document.querySelectorAll('.admin-kpi-tabs button').forEach((button,index)=>button.classList.toggle('active',index===(ADMIN_KPI_VIEW==='admin'?0:1)));main.scrollIntoView({behavior:'smooth',block:'start'});}

function adminKpiRender(){
 document.getElementById('admin-kpi-control')?.remove();if(!adminKpiRelevant())return;
 const root=document.createElement('div');root.id='admin-kpi-control';root.className='admin-kpi-control';
 if(ADMIN_KPI_STATE.loading){root.innerHTML='<section class="card pad"><h2>KPI Admin ตามตำแหน่ง</h2><p>กำลังโหลดชุดประเมินและสายผู้ประเมิน…</p></section>';main.prepend(root);return;}
 if(ADMIN_KPI_STATE.error){root.innerHTML=`<section class="card pad"><h2>KPI Admin ตามตำแหน่ง</h2><div class="ai-note"><b>ยังเปิดส่วนประเมินรายบุคคลไม่ได้</b><br>${esc(ADMIN_KPI_STATE.error)}${canAdminAccess()?'<br>ผู้ดูแลตรวจว่า Migration 037 ถูกใช้งานแล้ว':''}</div><button class="tbtn" onclick="loadAdminKpi(true)">ลองใหม่</button></section>`;main.prepend(root);return;}
 if(!ADMIN_KPI_STATE.loaded){root.innerHTML='<section class="card pad"><h2>KPI Admin ตามตำแหน่ง</h2><p>กำลังเตรียมข้อมูล…</p></section>';main.prepend(root);loadAdminKpi();return;}
 const current=ACCESS_PROFILE.department_code==='ADMIN'?adminKpiCardFor():null,own=ADMIN_KPI_STATE.evaluations.filter(e=>e.evaluatee_id===ACCESS_PROFILE.id),accessible=ADMIN_KPI_STATE.evaluations.filter(e=>e.evaluatee_id!==ACCESS_PROFILE.id),cards=[...ADMIN_KPI_STATE.scorecards].sort((a,b)=>['staff','lead','management'].indexOf(a.position_group)-['staff','lead','management'].indexOf(b.position_group));
 const profileLine=current?`ชุดของคุณ: <b>${esc(current.name)}</b>`:'มุมมองผู้ดูแล · เลือกพนักงาน Admin เพื่อเริ่มรอบประเมิน';
 root.innerHTML=`${adminKpiTabsHTML()}<div class="admin-kpi-body">${adminKpiPolicyHTML()}<section class="admin-kpi-hero"><div><span class="admin-kpi-eyebrow">KPI CONTROL CENTER · ADMIN</span><h2>ประเมินง่าย เห็นหลักฐานชัด และตรวจสอบย้อนหลังได้</h2><p>${profileLine} · รอบรายเดือน · คะแนนเต็ม 100</p></div><div class="admin-kpi-grade"><b>A</b><span>90–100</span><b>B</b><span>80–89</span><b>C</b><span>70–79</span><b>D</b><span>&lt; 70</span></div></section><section class="admin-kpi-summary"><div><b>3</b><span>ชุดตามตำแหน่ง</span></div><div><b>82</b><span>ตัวชี้วัดทั้งหมด</span></div><div><b>100</b><span>คะแนนเต็มทุกชุด</span></div><div><b>รายเดือน</b><span>รอบการประเมิน</span></div></section>${adminKpiFlowHTML()}<section class="admin-kpi-cards">${cards.map(s=>`<article class="card"><span>${esc(s.position_group==='staff'?'พนักงาน':s.position_group==='lead'?'รอง / ผู้ช่วยหัวหน้า / หัวหน้า':'บริหารแอดมิน')}</span><h3>${esc(s.name)}</h3><strong>${adminKpiItems(s.code).length} ตัวชี้วัด</strong><small>${adminKpiTotal(s.code)} คะแนน · เริ่ม ${esc(s.effective_from)}</small></article>`).join('')}</section>${adminKpiCanStart()?adminKpiStartHTML():''}${adminKpiCanConfigure()?'<button class="tbtn admin-kpi-config" onclick="openAdminKpiAssignment()">⚙ กำหนดสายผู้ประเมิน</button>':''}${adminKpiEvaluationList('ผลประเมินของฉัน',own)}${adminKpiEvaluationList('รายการที่รับผิดชอบ / ตรวจรับ',accessible)}</div>`;
 const anchor=document.getElementById('kpi-work-report');anchor?main.insertBefore(root,anchor):main.append(root);adminKpiArrangeLegacy();
}

function adminKpiStartHTML(){
 const people=TASK_PROFILES.filter(p=>p.active&&p.department_code==='ADMIN');
 return `<section class="card pad admin-kpi-start"><h3>เริ่มหรือเปิดผลประเมินรายเดือน</h3><label>ผู้รับการประเมิน<select class="fin" id="admin-kpi-person"><option value="">เลือกพนักงาน Admin</option>${people.map(p=>`<option value="${p.id}">${esc(p.display_name||p.email)} · ${esc(p.position_title||'ยังไม่ระบุตำแหน่ง')}</option>`).join('')}</select></label><label>เดือน<input class="fin" id="admin-kpi-month" type="month" value="${bangkokTodayISO().slice(0,7)}"></label><button class="tbtn primary" onclick="startAdminKpiEvaluation()">เปิดแบบประเมิน</button></section>`;
}
function adminKpiEvaluationList(title,rows){
 if(!rows.length)return'';return `<section class="card pad"><h3>${esc(title)}</h3><div class="admin-kpi-eval-list">${rows.sort((a,b)=>b.period_start.localeCompare(a.period_start)).map(e=>`<button onclick="openAdminKpiEvaluation('${e.id}')"><span><b>${esc(adminKpiName(e.evaluatee_id))}</b><small>${esc(e.period_start.slice(0,7))} · ${esc(ADMIN_KPI_STATUS[e.status]||e.status)} · ผู้ประเมิน ${esc(adminKpiName(e.evaluator_id))}</small></span><strong>${e.status==='voided'?'โมฆะ':e.total_score==null?'—':Number(e.total_score).toFixed(1)}</strong></button>`).join('')}</div></section>`;
}

async function ackAdminKpiPolicy(code){try{const r=await SB.rpc('acknowledge_kpi_policy',{p_notice:code});if(r.error)throw r.error;await loadAdminKpi(true);toast('บันทึกรับทราบประกาศแล้ว');}catch(e){toast('บันทึกรับทราบไม่สำเร็จ · '+e.message,'info');}}
async function startAdminKpiEvaluation(){const person=val('admin-kpi-person'),month=val('admin-kpi-month');if(!person||!/^[0-9]{4}-(0[1-9]|1[0-2])$/.test(month)){toast('กรุณาเลือกพนักงานและเดือน','info');return;}try{const r=await SB.rpc('start_admin_kpi_evaluation',{p_evaluatee:person,p_period_start:month+'-01'});if(r.error)throw r.error;await loadAdminKpi(true);openAdminKpiEvaluation(r.data.id);toast('เปิดแบบประเมินแล้ว');}catch(e){toast('เปิดแบบประเมินไม่สำเร็จ · '+e.message,'info');}}

function adminKpiScoreInput(e,item,saved,editable){const urls=Array.isArray(saved?.evidence_urls)?saved.evidence_urls.join('\n'):'';return `<article class="admin-kpi-item" data-item="${item.id}"><header><span>${esc(item.item_code)}</span><div><h4>${esc(item.name)}</h4><p>${esc(item.criteria)}</p></div><label>คะแนนเต็ม ${Number(item.max_score)}<input class="fin admin-kpi-score" type="number" min="0" max="${Number(item.max_score)}" step="0.5" value="${saved?.score??''}" ${editable?'':'disabled'}></label></header><details><summary>หลักฐานที่ต้องใช้</summary><p>${esc(item.evidence_requirements)}</p><label>คำอธิบาย/วิธีตรวจ<textarea class="fin admin-kpi-evidence" rows="2" ${editable?'':'disabled'}>${esc(saved?.evidence_note||'')}</textarea></label><label>ลิงก์หลักฐาน (หนึ่งลิงก์ต่อบรรทัด)<textarea class="fin admin-kpi-urls" rows="2" ${editable?'':'disabled'}>${esc(urls)}</textarea></label></details></article>`;}
function adminKpiFormRows(e){const items=adminKpiItems(e.scorecard_code),scores=new Map(ADMIN_KPI_STATE.scores.filter(s=>s.evaluation_id===e.id).map(s=>[s.item_id,s])),editable=e.evaluator_id===ACCESS_PROFILE.id&&['draft','returned'].includes(e.status);let last='';return items.map(item=>{const heading=item.category_code!==last?`<h3 class="admin-kpi-category">${esc(item.category_code)}. ${esc(item.category_name)} <span>${items.filter(x=>x.category_code===item.category_code).reduce((n,x)=>n+Number(x.max_score),0)} คะแนน</span></h3>`:'';last=item.category_code;return heading+adminKpiScoreInput(e,item,scores.get(item.id),editable);}).join('');}
function openAdminKpiEvaluation(id){
 const e=adminKpiEvaluation(id);if(!e)return;const editable=e.evaluator_id===ACCESS_PROFILE.id&&['draft','returned'].includes(e.status),review=adminKpiCanReview(e),voidable=adminKpiCanConfigure()&&e.status!=='voided';const comments=ADMIN_KPI_STATE.comments.filter(c=>c.evaluation_id===e.id);
 showModal(`<div class="modal-h"><div><span class="tag">${esc(ADMIN_KPI_STATUS[e.status]||e.status)} · ${esc(e.period_start.slice(0,7))}</span><h3>KPI · ${esc(adminKpiName(e.evaluatee_id))}</h3><p>${esc(ADMIN_KPI_STATE.scorecards.find(s=>s.code===e.scorecard_code)?.name||e.scorecard_code)} · ผู้ประเมิน ${esc(adminKpiName(e.evaluator_id))}</p></div><button class="x" onclick="closeModal()">×</button></div><form class="pad admin-kpi-form" id="admin-kpi-form">${e.return_reason?`<div class="ai-note"><b>เหตุผลที่ส่งกลับ</b><br>${esc(e.return_reason)}</div>`:''}${e.void_reason?`<div class="ai-note"><b>ผลประเมินเป็นโมฆะ</b><br>${esc(e.void_reason)}</div>`:''}<div class="admin-kpi-running">คะแนนที่กรอก <b id="admin-kpi-running-total">${Number(e.total_score||0).toFixed(1)}</b> / 100</div>${adminKpiFormRows(e)}<label>หมายเหตุผู้ประเมิน<textarea class="fin" id="admin-kpi-note" rows="3" ${editable?'':'disabled'}>${esc(e.evaluator_note||'')}</textarea></label><p id="admin-kpi-error" role="alert"></p>${editable?'<div class="ux-modal-actions"><button type="button" class="tbtn" onclick="saveAdminKpiDraft(\''+e.id+'\',false)">บันทึกร่าง</button><button type="button" class="tbtn primary" onclick="saveAdminKpiDraft(\''+e.id+'\',true)">บันทึกและส่งตรวจ</button></div>':''}${review?`<section class="admin-kpi-review"><h3>ตรวจรับผลประเมิน</h3><textarea class="fin" id="admin-kpi-review-reason" rows="3" placeholder="เหตุผลส่งกลับ (จำเป็นเมื่อส่งกลับ)"></textarea><button type="button" class="tbtn" onclick="reviewAdminKpi('${e.id}','return')">ส่งกลับแก้ไข</button><button type="button" class="tbtn primary" onclick="reviewAdminKpi('${e.id}','approve')">รับรองผล</button></section>`:''}${voidable?`<section class="admin-kpi-review danger"><h3>ควบคุมความโปร่งใส</h3><p>ใช้เมื่อมีข้อเท็จจริงว่าผลประเมินไม่โปร่งใส ระบบเก็บประวัติเดิมและเปิดรอบประเมินใหม่ได้</p><textarea class="fin" id="admin-kpi-void-reason" rows="3" placeholder="ข้อเท็จจริงและเหตุผลอย่างน้อย 20 ตัวอักษร"></textarea><button type="button" class="tbtn" onclick="voidAdminKpi('${e.id}')">ทำผลประเมินเป็นโมฆะ</button></section>`:''}<section class="admin-kpi-comments"><h3>คำถาม / ความเห็น</h3>${comments.map(c=>`<p><b>${esc(adminKpiName(c.author_id))}</b> · ${esc(new Date(c.created_at).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'}))}<br>${esc(c.body)}</p>`).join('')||'<p class="muted">ยังไม่มีความคิดเห็น</p>'}<textarea class="fin" id="admin-kpi-comment" rows="2" placeholder="สอบถามหรือชี้แจงเกี่ยวกับผลประเมิน"></textarea><button type="button" class="tbtn" onclick="commentAdminKpi('${e.id}')">ส่งความคิดเห็น</button></section></form>`);
 document.querySelectorAll('.admin-kpi-score').forEach(x=>x.oninput=()=>{const total=[...document.querySelectorAll('.admin-kpi-score')].reduce((n,i)=>n+(Number(i.value)||0),0);document.getElementById('admin-kpi-running-total').textContent=total.toFixed(1);});
}
function adminKpiCollectScores(){return [...document.querySelectorAll('.admin-kpi-item')].filter(row=>row.querySelector('.admin-kpi-score').value!=='').map(row=>{const evidence_urls=row.querySelector('.admin-kpi-urls').value.split(/\n|,/).map(x=>x.trim()).filter(Boolean);const bad=evidence_urls.find(url=>!/^https?:\/\/\S+$/i.test(url));if(bad)throw new Error(`ลิงก์หลักฐานต้องเริ่มด้วย http:// หรือ https:// (${bad})`);return{item_id:row.dataset.item,score:Number(row.querySelector('.admin-kpi-score').value),evidence_note:row.querySelector('.admin-kpi-evidence').value.trim(),evidence_urls};});}
async function saveAdminKpiDraft(id,submit){const e=adminKpiEvaluation(id),error=document.getElementById('admin-kpi-error'),buttons=document.querySelectorAll('#admin-kpi-form button');buttons.forEach(b=>b.disabled=true);try{const saved=await SB.rpc('save_admin_kpi_draft',{p_evaluation:id,p_scores:adminKpiCollectScores(),p_note:val('admin-kpi-note'),p_expected_version:e.version});if(saved.error)throw saved.error;let row=saved.data;if(submit){const sent=await SB.rpc('submit_admin_kpi_evaluation',{p_evaluation:id,p_expected_version:row.version});if(sent.error)throw sent.error;row=sent.data;}await loadAdminKpi(true);openAdminKpiEvaluation(id);toast(submit?'ส่งผลประเมินให้ตรวจรับแล้ว':'บันทึกร่างแล้ว');}catch(ex){error.textContent=ex.message;buttons.forEach(b=>b.disabled=false);}}
async function reviewAdminKpi(id,action){const e=adminKpiEvaluation(id),reason=val('admin-kpi-review-reason');try{const r=await SB.rpc('review_admin_kpi_evaluation',{p_evaluation:id,p_action:action,p_reason:reason,p_expected_version:e.version});if(r.error)throw r.error;closeModal();await loadAdminKpi(true);toast(action==='approve'?'รับรองผลประเมินแล้ว':'ส่งกลับให้แก้ไขแล้ว');}catch(ex){document.getElementById('admin-kpi-error').textContent=ex.message;}}
async function voidAdminKpi(id){const e=adminKpiEvaluation(id),reason=val('admin-kpi-void-reason');if(!confirm('ยืนยันทำผลประเมินนี้เป็นโมฆะ ระบบจะเก็บประวัติไว้และไม่นำคะแนนไปใช้ใช่หรือไม่?'))return;try{const r=await SB.rpc('void_admin_kpi_evaluation',{p_evaluation:id,p_reason:reason,p_expected_version:e.version});if(r.error)throw r.error;closeModal();await loadAdminKpi(true);toast('ทำผลประเมินเป็นโมฆะแล้ว กรุณาเริ่มประเมินใหม่โดยผู้เป็นกลาง');}catch(ex){document.getElementById('admin-kpi-error').textContent=ex.message;}}
async function commentAdminKpi(id){const body=val('admin-kpi-comment').trim();if(!body)return;try{const r=await SB.rpc('comment_admin_kpi_evaluation',{p_evaluation:id,p_body:body});if(r.error)throw r.error;await loadAdminKpi(true);openAdminKpiEvaluation(id);}catch(ex){document.getElementById('admin-kpi-error').textContent=ex.message;}}

function openAdminKpiAssignment(){const admins=TASK_PROFILES.filter(p=>p.active&&p.department_code==='ADMIN'),people=TASK_PROFILES.filter(p=>p.active),options=rows=>rows.map(p=>`<option value="${p.id}">${esc(p.display_name||p.email)} · ${esc(p.position_title||deptName(p.department_code))}</option>`).join('');showModal(`<div class="modal-h"><div><h3>กำหนดสายผู้ประเมิน KPI Admin</h3><p>กำหนดชื่อจริงแทนการอ้างอิงอีเมลร่วม</p></div><button class="x" onclick="closeModal()">×</button></div><form class="pad" id="admin-kpi-assignment"><label>ผู้รับการประเมิน<select class="fin" id="akpa-evaluatee" required><option value="">เลือก</option>${options(admins)}</select></label><label>ผู้ประเมิน<select class="fin" id="akpa-evaluator" required><option value="">เลือก</option>${options(people)}</select></label><label>ผู้ตรวจรับ<select class="fin" id="akpa-reviewer"><option value="">ทีมบริหาร/ทีม KPI ตรวจรับภายหลัง</option>${options(people)}</select></label><label>ชุด KPI<select class="fin" id="akpa-card"><option value="">เลือกอัตโนมัติตามตำแหน่ง</option>${ADMIN_KPI_STATE.scorecards.map(s=>`<option value="${s.code}">${esc(s.name)}</option>`).join('')}</select></label><label>เริ่มใช้เดือน<input class="fin" id="akpa-month" type="month" value="${bangkokTodayISO().slice(0,7)}" required></label><p id="akpa-error" role="alert"></p><button class="tbtn primary">บันทึกสายผู้ประเมิน</button></form>`);document.getElementById('admin-kpi-assignment').onsubmit=async ev=>{ev.preventDefault();const button=ev.target.querySelector('button');button.disabled=true;try{const r=await SB.rpc('set_admin_kpi_assignment',{p_evaluatee:val('akpa-evaluatee'),p_evaluator:val('akpa-evaluator'),p_reviewer:val('akpa-reviewer')||null,p_scorecard:val('akpa-card')||null,p_effective_from:val('akpa-month')+'-01'});if(r.error)throw r.error;closeModal();await loadAdminKpi(true);toast('บันทึกสายผู้ประเมินแล้ว');}catch(ex){document.getElementById('akpa-error').textContent=ex.message;button.disabled=false;}};}

const adminKpiBaseRender=RENDER.kpi;RENDER.kpi=function(){adminKpiBaseRender();adminKpiRender();};
const adminKpiBaseLogin=onLoggedIn;onLoggedIn=async function(session){const result=await adminKpiBaseLogin(session);if(ACCESS_PROFILE&&adminKpiRelevant())loadAdminKpi(true);return result;};

const adminKpiStyle=document.createElement('style');adminKpiStyle.textContent=`
.admin-kpi-control{display:grid;gap:18px;margin:18px 0 24px}.admin-kpi-body{display:grid;gap:18px}.admin-kpi-tabs{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:7px;border:1px solid var(--line);border-radius:16px;background:var(--surface)}.admin-kpi-tabs button{display:grid;grid-template-columns:36px 1fr;column-gap:10px;text-align:left;align-items:center;padding:14px;border:0;border-radius:11px;background:transparent;color:var(--muted);font-family:inherit;cursor:pointer}.admin-kpi-tabs button>span{grid-row:1/3;display:grid;place-items:center;width:34px;height:34px;border-radius:10px;background:var(--blue-50);color:var(--primary);font-size:11px;font-weight:700}.admin-kpi-tabs b{color:var(--ink);font-size:14px}.admin-kpi-tabs small{font-size:11px}.admin-kpi-tabs button.active{background:linear-gradient(135deg,#17479e,#2f6ee4);box-shadow:0 8px 24px rgba(37,99,235,.18)}.admin-kpi-tabs button.active b,.admin-kpi-tabs button.active small{color:#fff}.admin-kpi-tabs button.active>span{background:rgba(255,255,255,.18);color:#fff}.admin-kpi-notice{padding:20px 22px;display:grid;grid-template-columns:42px 1fr auto;gap:16px;border:1px solid #f4d58d;background:linear-gradient(120deg,#fffdf4,var(--surface))}.admin-kpi-notice-icon{display:grid;place-items:center;width:38px;height:38px;border-radius:11px;background:#fff3cf;color:#9a6700;font-weight:800}.admin-kpi-eyebrow{font-size:11px;font-weight:700;letter-spacing:1px;color:var(--primary)}.admin-kpi-notice h2,.admin-kpi-hero h2{font-size:21px;margin:5px 0}.admin-kpi-policy-points{display:flex;flex-wrap:wrap;gap:7px;margin:10px 0}.admin-kpi-policy-points span{padding:5px 9px;border-radius:999px;background:#fff7d7;color:#765200;font-size:11px}.admin-kpi-notice details summary{color:var(--primary);font-size:12px;font-weight:600;cursor:pointer}.admin-kpi-notice p,.admin-kpi-hero p,.admin-kpi-flow p{color:var(--muted);line-height:1.75}.admin-kpi-ack{display:grid;place-items:end;align-content:center;gap:10px;min-width:150px;font-size:12px}.admin-kpi-ack.is-ack span{padding:8px 12px;border-radius:999px;background:#e8f7ee;color:#18794e;font-weight:600}.admin-kpi-hero{display:grid;grid-template-columns:1fr auto;gap:22px;padding:28px;border-radius:20px;color:#fff;background:radial-gradient(circle at 85% 15%,rgba(109,162,255,.7),transparent 28%),linear-gradient(125deg,#102f70,#225bc4)}.admin-kpi-hero p{color:#e5edff}.admin-kpi-grade{display:grid;grid-template-columns:auto auto;gap:4px 12px;align-content:center;padding:12px 16px;border:1px solid rgba(255,255,255,.18);border-radius:14px;background:rgba(255,255,255,.09)}.admin-kpi-grade b{font-size:18px}.admin-kpi-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.admin-kpi-summary div{padding:16px 18px;border:1px solid var(--line);border-radius:14px;background:var(--surface)}.admin-kpi-summary b{display:block;font-size:22px;color:var(--primary)}.admin-kpi-summary span{font-size:11px;color:var(--muted)}.admin-kpi-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.admin-kpi-cards article{padding:20px;display:grid;gap:6px;border-top:3px solid var(--primary)}.admin-kpi-cards span,.admin-kpi-cards small{color:var(--muted);font-size:11px}.admin-kpi-cards strong{font-size:24px}.admin-kpi-flow-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin:14px 0}.admin-kpi-flow-grid div{position:relative;padding:14px;border:1px solid var(--line);border-radius:12px;background:var(--surface)}.admin-kpi-flow-grid div:not(:last-child):after{content:'›';position:absolute;right:-9px;top:24px;color:var(--primary);font-weight:800;z-index:2}.admin-kpi-flow-grid span{display:block;color:var(--muted);font-size:11px;margin-top:4px}.admin-kpi-start{display:flex;align-items:end;gap:12px;flex-wrap:wrap;border:1px solid #bfd3ff;background:linear-gradient(135deg,var(--surface),var(--blue-50))}.admin-kpi-start h3{width:100%;margin-bottom:0}.admin-kpi-start label{display:grid;gap:5px;min-width:220px;flex:1}.admin-kpi-config{justify-self:start}.admin-kpi-eval-list{display:grid;gap:8px}.admin-kpi-eval-list button{display:flex;justify-content:space-between;align-items:center;text-align:left;width:100%;padding:13px;border:1px solid var(--line);border-radius:10px;background:var(--surface);color:var(--ink)}.admin-kpi-eval-list small{display:block;color:var(--muted);margin-top:4px}.admin-kpi-eval-list strong{font-size:22px}.admin-kpi-form{padding-top:12px!important}.admin-kpi-running{position:sticky;top:0;z-index:4;padding:12px 16px;margin:-12px 0 12px;background:var(--blue-50);border:1px solid var(--line);border-radius:10px;text-align:right}.admin-kpi-category{display:flex;justify-content:space-between;gap:12px;margin:22px 0 8px;padding:12px;background:var(--blue-50);border-radius:10px}.admin-kpi-category span{font-size:12px;color:var(--muted)}.admin-kpi-item{border:1px solid var(--line);border-radius:12px;margin:9px 0;overflow:hidden}.admin-kpi-item header{display:grid;grid-template-columns:42px 1fr 130px;gap:12px;padding:14px;align-items:start}.admin-kpi-item header>span{display:grid;place-items:center;width:36px;height:36px;border-radius:9px;background:var(--blue-50);color:var(--primary);font-weight:600}.admin-kpi-item h4{margin:0}.admin-kpi-item p{color:var(--muted);font-size:12px}.admin-kpi-item header label{font-size:11px;text-align:right}.admin-kpi-item header input{margin-top:5px;text-align:right}.admin-kpi-item details{border-top:1px solid var(--line);padding:12px 16px}.admin-kpi-item details summary{cursor:pointer;font-weight:500}.admin-kpi-item details label{display:grid;gap:5px;margin-top:10px}.admin-kpi-review,.admin-kpi-comments{padding:16px;margin:18px 0;border:1px solid var(--line);border-radius:12px}.admin-kpi-review.danger{border-color:#e5a79e}.admin-kpi-review textarea,.admin-kpi-comments textarea{margin:10px 0}.admin-kpi-comments p{padding:8px 0;border-bottom:1px solid var(--line-2)}#main:not(.admin-kpi-evidence-view)>.admin-kpi-legacy{display:none!important}#main.admin-kpi-evidence-view #admin-kpi-control .admin-kpi-body{display:none}#main.admin-kpi-evidence-view #admin-kpi-control{margin-bottom:12px}@media(max-width:900px){.admin-kpi-cards,.admin-kpi-summary{grid-template-columns:1fr 1fr}.admin-kpi-flow-grid{grid-template-columns:1fr 1fr}.admin-kpi-notice,.admin-kpi-hero{grid-template-columns:1fr}.admin-kpi-ack{place-items:start}.admin-kpi-item header{grid-template-columns:36px 1fr}.admin-kpi-item header label{grid-column:1/-1;text-align:left}.admin-kpi-flow-grid div:after{display:none}}@media(max-width:520px){.admin-kpi-tabs,.admin-kpi-cards,.admin-kpi-summary,.admin-kpi-flow-grid{grid-template-columns:1fr}.admin-kpi-item header{padding:12px}.admin-kpi-notice,.admin-kpi-hero{padding:18px}}
`;document.head.append(adminKpiStyle);
